#include "stdlib/blas/ext/base/ndarray/dediff.h"
#include "stdlib/blas/ext/base/dediff.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"

/**
* Calculates the differences between consecutive elements of a one-dimensional double-precision floating-point ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a one-dimensional ndarray containing values to prepend.
*     -   a one-dimensional ndarray containing values to append.
*     -   a one-dimensional output ndarray.
*
* @param arrays    list containing ndarrays
*/
void stdlib_blas_ext_dediff( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];
	const struct ndarray *prepend = arrays[ 1 ];
	const struct ndarray *append = arrays[ 2 ];
	const struct ndarray *out = arrays[ 3 ];

	const CBLAS_INT N = stdlib_ndarray_dimension( x, 0 );
	const CBLAS_INT strideX = stdlib_ndarray_stride_elements( x, 0 );
	const CBLAS_INT offsetX = stdlib_ndarray_offset_elements( x );

	const CBLAS_INT N1 = stdlib_ndarray_dimension( prepend, 0 );
	const CBLAS_INT strideP = stdlib_ndarray_stride_elements( prepend, 0 );
	const CBLAS_INT offsetP = stdlib_ndarray_offset_elements( prepend );

	const CBLAS_INT N2 = stdlib_ndarray_dimension( append, 0 );
	const CBLAS_INT strideA = stdlib_ndarray_stride_elements( append, 0 );
	const CBLAS_INT offsetA = stdlib_ndarray_offset_elements( append );

	const CBLAS_INT strideOut = stdlib_ndarray_stride_elements( out, 0 );
	const CBLAS_INT offsetOut = stdlib_ndarray_offset_elements( out );

	const double *dataX = (const double *)stdlib_ndarray_data( x );
	const double *dataP = (const double *)stdlib_ndarray_data( prepend );
	const double *dataA = (const double *)stdlib_ndarray_data( append );
	double *dataOut = (double *)stdlib_ndarray_data( out );
	API_SUFFIX(stdlib_strided_dediff_ndarray)( N, dataX, strideX, offsetX, N1, dataP, strideP, offsetP, N2, dataA, strideA, offsetA, dataOut, strideOut, offsetOut );
}
